"""Golden-scene comparison tests. Every image here is generated by the test."""
import importlib.util
import json
from pathlib import Path
import struct
import subprocess
import sys
import tempfile
import time
import unittest
import zlib

ROOT = Path(__file__).resolve().parents[1]
TOOL = ROOT / "tools/bench/golden.py"


def load_tool():
    spec = importlib.util.spec_from_file_location("bench_golden", TOOL)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


golden = load_tool()


def run_tool(*args):
    return subprocess.run(
        [sys.executable, str(TOOL), *map(str, args)],
        capture_output=True,
        text=True,
        encoding="utf-8",
    )


def pattern(width, height, channels=3, shift=0):
    """A textured image so SSIM has real structure to compare."""
    pixels = bytearray()
    for y in range(height):
        for x in range(width):
            rgb = ((x * 7 + y * 13) % 200, (x * 3 + y * 5) % 200, (x * x + y * 11) % 200)
            pixels += bytes(min(255, max(0, value + shift)) for value in rgb)
            if channels == 4:
                pixels.append((x + y) % 256)
    return golden.Image(width, height, channels, bytes(pixels))


def with_pixel(image, x, y, rgb):
    pixels = bytearray(image.pixels)
    offset = (y * image.width + x) * image.channels
    pixels[offset:offset + 3] = bytes(rgb)
    return golden.Image(image.width, image.height, image.channels, bytes(pixels))


def chunk(kind, data):
    body = kind + data
    return struct.pack(">I", len(data)) + body + struct.pack(">I", zlib.crc32(body) & 0xFFFFFFFF)


def paeth(a, b, c):
    p = a + b - c
    pa, pb, pc = abs(p - a), abs(p - b), abs(p - c)
    if pa <= pb and pa <= pc:
        return a
    return b if pb <= pc else c


def filter_rows(image, filters):
    """Independent PNG filter encoder: row y uses filters[y % len(filters)]."""
    bpp, stride = image.channels, image.width * image.channels
    out, previous = bytearray(), bytes(stride)
    for y in range(image.height):
        row = image.pixels[y * stride:(y + 1) * stride]
        kind = filters[y % len(filters)]
        encoded = bytearray()
        for i, value in enumerate(row):
            left = row[i - bpp] if i >= bpp else 0
            up = previous[i]
            corner = previous[i - bpp] if i >= bpp else 0
            predictor = (0, left, up, (left + up) // 2, paeth(left, up, corner))[kind]
            encoded.append((value - predictor) & 0xFF)
        out += bytes([kind]) + encoded
        previous = row
    return bytes(out)


def stored_zlib(data):
    """zlib stream of stored (uncompressed) deflate blocks, as fable2_frame_capture.h writes it."""
    out = bytearray(b"\x78\x01")
    offset = 0
    while True:
        block = data[offset:offset + 65535]
        offset += len(block)
        last = offset >= len(data)
        out += bytes([1 if last else 0]) + struct.pack("<HH", len(block), len(block) ^ 0xFFFF) + block
        if last:
            break
    return bytes(out + struct.pack(">I", zlib.adler32(data) & 0xFFFFFFFF))


def build_png(image, filters=(0,), compress=True, idat_parts=1, bit_depth=8, color_type=None, interlace=0):
    if color_type is None:
        color_type = 2 if image.channels == 3 else 6
    raw = filter_rows(image, filters)
    stream = zlib.compress(raw, 9) if compress else stored_zlib(raw)
    size = -(-len(stream) // idat_parts)
    header = struct.pack(">IIBBBBB", image.width, image.height, bit_depth, color_type, 0, 0, interlace)
    body = chunk(b"IHDR", header) + chunk(b"tEXt", b"Comment\x00synthetic")
    for start in range(0, len(stream), size):
        body += chunk(b"IDAT", stream[start:start + size])
    return b"\x89PNG\r\n\x1a\n" + body + chunk(b"IEND", b"")


class GoldenTestCase(unittest.TestCase):
    def setUp(self):
        directory = tempfile.TemporaryDirectory(prefix="fable2-golden-test-")
        self.addCleanup(directory.cleanup)
        self.tmp = Path(directory.name)
        self.ref = self.tmp / "reference"
        self.cand = self.tmp / "candidate"
        self.ref.mkdir()
        self.cand.mkdir()

    def save(self, directory, name, image):
        path = directory / f"{name}.png"
        path.write_bytes(build_png(image))
        return path

    def compare(self, *extra):
        out = self.tmp / "summary.json"
        result = run_tool("compare", self.ref, self.cand, "--out", out, *extra)
        summary = json.loads(out.read_text(encoding="utf-8")) if out.exists() else None
        return result, summary

    def scene(self, summary, name):
        return next(entry for entry in summary["scenes"] if entry["scene"] == name)


class PngCodecTests(GoldenTestCase):
    def test_decodes_every_filter_type_for_rgb_and_rgba(self):
        for channels in (3, 4):
            for kind in range(5):
                with self.subTest(channels=channels, filter=kind):
                    image = pattern(13, 9, channels)
                    self.assertEqual(golden.decode_png(build_png(image, filters=(kind,))), image)

    def test_decodes_mixed_filters_split_idat_and_ancillary_chunks(self):
        image = pattern(17, 11, 4)
        data = build_png(image, filters=(0, 1, 2, 3, 4), idat_parts=3)
        self.assertEqual(golden.decode_png(data), image)

    def test_decodes_uncompressed_png_like_frame_capture(self):
        # Rows of 1280 RGB pixels span several 65535-byte stored blocks.
        image = pattern(1280, 40)
        data = build_png(image, compress=False)
        self.assertEqual(golden.decode_png(data), image)

    def test_encoder_round_trips(self):
        for channels in (3, 4):
            image = pattern(10, 6, channels)
            self.assertEqual(golden.decode_png(golden.encode_png(image)), image)

    def test_rejects_unsupported_or_damaged_png(self):
        image = pattern(4, 4)
        good = build_png(image)
        text_data = 8 + 25 + 8  # signature, IHDR chunk, tEXt length and type
        cases = {
            "not a PNG": b"GIF89a" + bytes(20),
            "16-bit": build_png(image, bit_depth=16),
            "palette": build_png(image, color_type=3),
            "interlaced": build_png(image, interlace=1),
            "bad CRC": good[:text_data] + b"X" + good[text_data + 1:],
            "truncated": good[:60],
        }
        for label, data in cases.items():
            with self.subTest(label):
                with self.assertRaises(golden.GoldenError):
                    golden.decode_png(data)


class MetricTests(unittest.TestCase):
    def test_identical_images_score_one(self):
        image = pattern(32, 24)
        self.assertAlmostEqual(golden.ssim(image, image), 1.0, places=9)
        self.assertEqual(golden.diff_fraction(image, image, 0), 0.0)

    def test_one_pixel_change(self):
        image = pattern(32, 24)
        changed = with_pixel(image, 31, 23, (255, 255, 255))
        self.assertEqual(golden.diff_fraction(image, changed, 8), 1 / (32 * 24))
        self.assertLess(golden.ssim(image, changed), 1.0)

    def test_tolerance_ignores_small_channel_differences(self):
        image = pattern(16, 16)
        self.assertEqual(golden.diff_fraction(image, pattern(16, 16, shift=3), 3), 0.0)
        self.assertEqual(golden.diff_fraction(image, pattern(16, 16, shift=4), 3), 1.0)

    def test_alpha_is_ignored(self):
        self.assertEqual(golden.diff_fraction(pattern(8, 8, 3), pattern(8, 8, 4), 0), 0.0)
        self.assertAlmostEqual(golden.ssim(pattern(8, 8, 3), pattern(8, 8, 4)), 1.0, places=9)

    def test_brightness_shift_lowers_ssim(self):
        self.assertLess(golden.ssim(pattern(32, 32), pattern(32, 32, shift=50)), 0.98)

    def test_full_resolution_pair_is_fast(self):
        reference = pattern(1280, 720)
        candidate = with_pixel(reference, 640, 360, (0, 0, 0))
        start = time.perf_counter()
        golden.ssim(reference, candidate)
        golden.diff_fraction(reference, candidate, 8)
        self.assertLess(time.perf_counter() - start, 15)


class CompareCommandTests(GoldenTestCase):
    def test_identical_scenes_pass(self):
        self.save(self.ref, "town", pattern(32, 24))
        self.save(self.cand, "town", pattern(32, 24))
        result, summary = self.compare()
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertIn("town", result.stdout)
        self.assertIn("RESULT: pass", result.stdout)
        entry = self.scene(summary, "town")
        self.assertEqual(entry["status"], "pass")
        self.assertEqual(entry["ssim"], 1.0)
        self.assertEqual(entry["diff_fraction"], 0.0)
        self.assertEqual(summary["result"], "pass")

    def test_one_pixel_change_is_reported_and_gated_by_threshold(self):
        image = pattern(32, 24)
        self.save(self.ref, "town", image)
        self.save(self.cand, "town", with_pixel(image, 3, 4, (255, 0, 255)))
        result, summary = self.compare()
        self.assertEqual(result.returncode, 0, result.stdout)
        self.assertAlmostEqual(self.scene(summary, "town")["diff_fraction"], 1 / 768, places=6)

        result, summary = self.compare("--max-diff-fraction", "0")
        self.assertEqual(result.returncode, 1)
        self.assertIn("FAIL", result.stdout)
        self.assertEqual(self.scene(summary, "town")["status"], "fail")

    def test_brightness_shift_fails(self):
        self.save(self.ref, "cave", pattern(32, 32))
        self.save(self.cand, "cave", pattern(32, 32, shift=50))
        result, summary = self.compare()
        self.assertEqual(result.returncode, 1)
        entry = self.scene(summary, "cave")
        self.assertEqual(entry["status"], "fail")
        self.assertEqual(entry["diff_fraction"], 1.0)
        self.assertLess(entry["ssim"], 0.98)

    def test_low_ssim_alone_fails(self):
        # Tolerance 255 means no pixel counts as different, so only SSIM can fail.
        self.save(self.ref, "cave", pattern(32, 32))
        self.save(self.cand, "cave", pattern(32, 32, shift=50))
        result, summary = self.compare("--tolerance", "255")
        self.assertEqual(result.returncode, 1)
        entry = self.scene(summary, "cave")
        self.assertEqual(entry["diff_fraction"], 0.0)
        self.assertEqual(entry["status"], "fail")
        self.assertIn("SSIM", " ".join(entry["reasons"]))

    def test_size_mismatch_fails(self):
        self.save(self.ref, "menu", pattern(32, 24))
        self.save(self.cand, "menu", pattern(24, 32))
        result, summary = self.compare()
        self.assertEqual(result.returncode, 1)
        entry = self.scene(summary, "menu")
        self.assertEqual(entry["status"], "fail")
        self.assertIsNone(entry["ssim"])
        self.assertIn("size", " ".join(entry["reasons"]))
        self.assertIn("32x24", result.stdout)

    def test_missing_candidate_scene_fails(self):
        self.save(self.ref, "town", pattern(16, 16))
        self.save(self.ref, "cave", pattern(16, 16))
        self.save(self.cand, "town", pattern(16, 16))
        result, summary = self.compare()
        self.assertEqual(result.returncode, 1)
        self.assertIn("cave", result.stdout)
        self.assertEqual(self.scene(summary, "cave")["status"], "missing")
        self.assertEqual(self.scene(summary, "town")["status"], "pass")
        self.assertEqual(summary["result"], "fail")

    def test_extra_candidate_scene_is_listed_but_does_not_fail(self):
        self.save(self.ref, "town", pattern(16, 16))
        self.save(self.cand, "town", pattern(16, 16))
        self.save(self.cand, "bonus", pattern(16, 16))
        result, summary = self.compare()
        self.assertEqual(result.returncode, 0, result.stdout)
        self.assertEqual(summary["extra_candidates"], ["bonus"])

    def test_unreadable_candidate_is_an_error(self):
        self.save(self.ref, "town", pattern(16, 16))
        (self.cand / "town.png").write_bytes(b"not a png")
        result, summary = self.compare()
        self.assertEqual(result.returncode, 1)
        self.assertEqual(self.scene(summary, "town")["status"], "error")

    def test_summary_records_thresholds_and_hashes(self):
        path = self.save(self.ref, "town", pattern(16, 16))
        self.save(self.cand, "town", pattern(16, 16))
        result, summary = self.compare("--min-ssim", "0.95", "--max-diff-fraction", "0.02", "--tolerance", "4")
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertEqual(summary["thresholds"], {"min_ssim": 0.95, "max_diff_fraction": 0.02, "tolerance": 4})
        import hashlib

        self.assertEqual(self.scene(summary, "town")["reference_sha256"], hashlib.sha256(path.read_bytes()).hexdigest())
        self.assertNotIn(str(self.tmp), json.dumps(summary))

    def test_default_summary_goes_to_candidate_dir(self):
        self.save(self.ref, "town", pattern(16, 16))
        self.save(self.cand, "town", pattern(16, 16))
        result = run_tool("compare", self.ref, self.cand)
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertTrue((self.cand / "golden_summary.json").is_file())

    def test_diff_dir_gets_one_image_per_failing_scene(self):
        image = pattern(16, 16)
        self.save(self.ref, "same", image)
        self.save(self.cand, "same", image)
        self.save(self.ref, "changed", image)
        self.save(self.cand, "changed", pattern(16, 16, shift=50))
        diff_dir = self.tmp / "diffs"
        result, summary = self.compare("--diff-dir", diff_dir)
        self.assertEqual(result.returncode, 1)
        self.assertEqual(sorted(p.name for p in diff_dir.iterdir()), ["changed.diff.png"])
        diff = golden.read_png(diff_dir / "changed.diff.png")
        self.assertEqual((diff.width, diff.height), (16, 16))
        self.assertEqual(self.scene(summary, "changed")["diff_image"], "changed.diff.png")
        self.assertIsNone(self.scene(summary, "same")["diff_image"])

    def test_diff_dir_marks_only_changed_pixels(self):
        image = pattern(8, 8)
        self.save(self.ref, "town", image)
        self.save(self.cand, "town", with_pixel(image, 2, 5, (255, 255, 255)))
        diff_dir = self.tmp / "diffs"
        self.compare("--max-diff-fraction", "0", "--diff-dir", diff_dir)
        diff = golden.read_png(diff_dir / "town.diff.png")
        marked = [i // 3 for i in range(0, len(diff.pixels), 3) if diff.pixels[i:i + 3] == b"\xff\x00\x00"]
        self.assertEqual(marked, [5 * 8 + 2])

    def test_invalid_arguments_exit_two(self):
        self.save(self.ref, "town", pattern(8, 8))
        self.save(self.cand, "town", pattern(8, 8))
        cases = [
            ("--min-ssim", "1.5"),
            ("--max-diff-fraction", "-0.1"),
            ("--tolerance", "256"),
            ("--diff-dir", self.cand),
        ]
        for case in cases:
            with self.subTest(case):
                self.assertEqual(run_tool("compare", self.ref, self.cand, *case).returncode, 2)
        self.assertEqual(run_tool("compare", self.tmp / "nope", self.cand).returncode, 2)
        empty = self.tmp / "empty"
        empty.mkdir()
        self.assertEqual(run_tool("compare", empty, self.cand).returncode, 2)


if __name__ == "__main__":
    unittest.main()
